<script setup lang="ts">import { useAppStore } from '@/stores/app';import { exportData } from '@/services/storage';import UiIcon from '@/components/UiIcon.vue';const store=useAppStore();const changed=()=>{store.applyTheme();store.persist()};const importFile=async(event:Event)=>{const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;store.data=JSON.parse(await file.text());store.persist();store.applyTheme()}</script>
<template><section><div class="page-heading"><div><p class="kicker">APLIKACJA</p><h1>Ustawienia</h1><p>Dopasuj wygląd i zarządzaj lokalnymi danymi.</p></div></div><div class="settings-grid"><article class="card form"><h2>Wygląd i język</h2><label>Motyw<select v-model="store.data.settings.theme" @change="changed"><option value="dark">Ciemny</option><option value="light">Jasny</option><option value="system">Systemowy</option></select></label><label>Waluta<select v-model="store.data.settings.currency" @change="store.persist"><option>PLN</option><option>EUR</option><option>USD</option></select></label><label>Język<select v-model="store.data.settings.locale" @change="store.persist"><option value="pl">Polski</option><option value="en">English</option></select></label></article><article class="card form"><h2>Dane i kopie zapasowe</h2><p class="muted">Eksport zawiera finanse, projekty i zaszyfrowany sejf. Hasła pozostają zaszyfrowane.</p><button class="button secondary" @click="exportData(store.data)"><UiIcon name="Download"/> Eksportuj JSON</button><label class="button secondary file-button"><UiIcon name="Upload"/> Importuj JSON<input accept="application/json" type="file" @change="importFile"></label></article><article class="card privacy-card"><UiIcon name="ShieldCheck" :size="30"/><div><h2>Prywatność przede wszystkim</h2><p>Brak konta, reklam i zewnętrznego śledzenia. Dane są zapisywane wyłącznie na Twoim urządzeniu.</p></div></article></div></section></template>
